using Microsoft.EntityFrameworkCore;

// Cosmos DB project context demonstrating EF Core 9 breaking-change fixes.
class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();
    public DbSet<Car> Cars => Set<Car>();
    public DbSet<Truck> Trucks => Set<Truck>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=KEY",
            "VehicleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // ─── Breaking Change #1: Discriminator property name ───────────────
        // EF Core 9 Cosmos provider changed the default discriminator property
        // from "Discriminator" to "$type". Existing documents still use
        // "Discriminator", so we must explicitly configure it to keep
        // compatibility with existing data.
        modelBuilder.Entity<Vehicle>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Vehicle>("Vehicle")
            .HasValue<Car>("Car")
            .HasValue<Truck>("Truck");

        modelBuilder.Entity<Vehicle>().ToContainer("Vehicles");
        modelBuilder.Entity<Vehicle>().HasPartitionKey(v => v.PartitionKey);
    }
}

// ─── Breaking Change #2: Synchronous I/O no longer supported ────────────
// EF Core 9 Cosmos provider removed all synchronous query APIs (ToList(),
// First(), Single(), etc.). You must switch to async equivalents.
class VehicleService
{
    private readonly CosmosDbContext _db;
    public VehicleService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 — sync, now throws InvalidOperationException in EF 9):
    //   var cars = _db.Cars.Where(c => c.Year > 2020).ToList();
    //   var truck = _db.Trucks.First(t => t.Id == id);

    // AFTER (EF Core 9 — must use async):
    public async Task<List<Car>> GetRecentCarsAsync()
    {
        return await _db.Cars
            .Where(c => c.Year > 2020)
            .ToListAsync();
    }

    public async Task<Truck> GetTruckAsync(string id)
    {
        return await _db.Trucks
            .FirstAsync(t => t.Id == id);
    }
}

class Vehicle
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public int Year { get; set; }
}
class Car : Vehicle { public int Doors { get; set; } }
class Truck : Vehicle { public double PayloadTons { get; set; } }

